import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()

    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
              for s in wb_root.find("m:sheets", NS)]

    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels_root}

    def col_to_idx(ref):
        m = re.match(r"([A-Z]+)(\d+)", ref)
        idx = 0
        for ch in m.group(1):
            idx = idx * 26 + (ord(ch) - ord("A") + 1)
        return idx - 1

    for name, rid in sheets:
        target = rel_map[rid].lstrip("/")
        if not target.startswith("xl/"):
            target = "xl/" + target
        print(f"=== Sheet: {name} (file {target}) ===")
        sheet_root = ET.fromstring(z.read(target))
        for row in sheet_root.find("m:sheetData", NS):
            row_num = row.get("r")
            cells = {}
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                isel = c.find("m:is", NS)
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                elif v is not None:
                    val = v.text
                else:
                    val = None
                cells[col_to_idx(ref)] = val
            if cells:
                maxcol = max(cells)
                print(row_num, [cells.get(i) for i in range(maxcol + 1)])

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

with zipfile.ZipFile("budget.xlsx") as z:
    root = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

rows = {}
for row in root.find("m:sheetData", NS):
    cells = {}
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        col = re.match(r"([A-Z]+)", ref).group(1)
        v = c.find("m:v", NS)
        cells[col] = float(v.text) if v is not None and c.get("t") != "s" else (v.text if v is not None else None)
    rows[int(row.get("r"))] = cells

expenses = []
for r in range(11, 23):
    amount = rows[r].get("C")
    expenses.append((rows[r].get("A"), rows[r].get("B"), amount))

total = sum(a for _, _, a in expenses)
print("Expense rows (Category, Item, Amount):")
for cat, item, amt in expenses:
    print(f"  {cat:15s} {item:15s} {amt:>8.2f}")
print(f"\nTotal Expenses: {total:.2f}")

by_cat = {}
for cat, item, amt in expenses:
    by_cat.setdefault(cat, 0.0)
    by_cat[cat] += amt
print("\nPer-category subtotals:")
for cat, amt in by_cat.items():
    print(f"  {cat:15s} {amt:>8.2f}")

